css:
/* llm-plugin: 스레드 정보 카드 아래, 따로 스크롤되는 명령 안내 상자 (plugins/t3-guide/build_theme.py로 생성) */
[data-thread-details-panel="inline"] { display: flex !important; flex-direction: column; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
[data-thread-details-panel="inline"] > [data-thread-details-card] { flex: 0 1 auto; min-height: 0; position: sticky; top: 0; }
[data-thread-details-panel="inline"] > [data-thread-details-card] [data-slot="scroll-area-viewport"] { overscroll-behavior-y: contain; }
[data-thread-details-panel="inline"]::after {
  display: block; flex: none; width: 100%; height: 682px; margin: 8px 0 -298px; font-size: 0; line-height: 0;
  background: var(--popover); clip-path: inset(0 0 298px 0 round 1rem);
  animation: llm-guide-window linear both; animation-timeline: scroll(nearest block);
}
@keyframes llm-guide-window { from { clip-path: inset(0 0 298px 0 round 1rem); } to { clip-path: inset(298px 0 0 0 round 1rem); } }
[data-thread-details-panel="inline"]::before {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 384px; z-index: 2; pointer-events: none;
  box-sizing: border-box; border: 1px solid color-mix(in srgb, var(--contrast-foreground) 10%, transparent); border-radius: 1rem;
  animation: llm-guide-frame linear both; animation-timeline: scroll(nearest block);
}
@keyframes llm-guide-frame { from { transform: translateY(0); } to { transform: translateY(298px); } }
.dark [data-thread-details-panel="inline"]::after { content: url("data:image/svg+xml;base64,"); }
:root:not(.dark) [data-thread-details-panel="inline"]::after { content: url("data:image/svg+xml;base64,"); }
